test_a_forbidden_pair_is_never_used:
for (crew, site), c in cost.items():
    lsa.add_arc_with_cost(crews.index(crew), sites.index(site), c)
for crew in crews:
    for site in sites:
        lsa.add_arc_with_cost(crews.index(crew), sites.index(site), cost.get((crew, site), 0))

test_a_site_no_crew_may_take_gives_no_pl:
for (crew, site), c in cost.items():
    lsa.add_arc_with_cost(crews.index(crew), sites.index(site), c)
for crew in crews:
    for site in sites:
        lsa.add_arc_with_cost(crews.index(crew), sites.index(site), cost.get((crew, site), 10**6))
